"""quantized_lstm on Triton for BI-V150.

Semantics taken from the operative pytest: the reference is a *sequential fp32*
LSTM over the dequantized int8 weights, where every operand (activations, h0/c0
and the dequantized weights) is first rounded to the activation dtype and then
upcast to fp32.  All gate math, the c/h recurrence and the accumulation happen
in fp32.

Implementation shape:
  * the packed CellParamsBase object is unpacked on the host through its own
    ``unpack()`` method into raw int8 storage plus per-tensor scale/zero point;
  * the dequantisation kernel emits each weight matrix pre-transposed and
    gate-interleaved: (K, 4H) with column ``h*4 + gate``.  A hidden tile is then
    a contiguous column slice of that matrix, so a consumer loads its weight
    tile coalesced and never builds a transposed staging tile;
  * the input-side gate GEMM ``x_t @ W_ih^T`` does not depend on the recurrence,
    so it is computed for all timesteps at once by one larger GEMM (M = T*N) whose
    M dimension is far better for the dot than T small ones, and one
    dequantisation of the whole quantized input replaces one launch per step;
  * one kernel per timestep adds ``h_{t-1} @ W_hh^T`` to that precomputed term
    with a *single* dot whose N dimension is the four gates of a hidden tile
    (4*BLOCK_H) instead of four narrow transposed dots; the gates are recovered
    from the interleaved columns with reshape + tl.split, so all gate math, the
    c/h update and the outputs are unchanged;
  * the recurrence state stays fp32; the returned tensors are cast to the
    activation dtype at the end.

The split keeps the reference accumulation order: the x term is summed over K in
the same block order as before and stored as fp32 (an fp32 register value is
exactly representable in memory), and the h terms are added to it in the same
order the single fused kernel used.

No framework arithmetic produces the numerical result.
"""

import torch
import triton
import triton.language as tl


def _pick_config(n, h):
    """Fixed launch shape.

    Triton's autotuner was measured on this backend to mis-launch (a 'tl.dot K>=16'
    compile error on tiny shapes and a wrong fp16 batch=1 result) although every
    declared configuration is exact when launched directly with its own
    num_warps/num_stages, so the configuration is chosen on the host instead.

    BLOCK_H follows the hidden size: with H<=256 a 32-wide tile gives only 8
    programs (8 of the 16 compute units) while a 16-wide tile fills all 16 and
    was measured to cut 5-33% off those shapes; for H=512 a 32-wide tile already
    gives 16 programs and performed better.
    """
    bn = 16 if n <= 16 else (32 if n <= 32 else 64)
    bh = 16 if h <= 256 else 32
    return bn, bh, 64, (4 if bn <= 32 else 8)


@triton.jit
def _dequant_t_kernel(
    w_ptr,
    out_ptr,
    K,
    H,
    scale,
    zp,
    BLOCK_K: tl.constexpr,
    BLOCK_H: tl.constexpr,
):
    """(4H, K) int8 gate-major rows -> (K, 4H) odtype with column h*4 + gate.

    Each gate tile is loaded coalesced along K and stored transposed, so the
    consumers never transpose a weight tile inside the recurrence.
    """
    pid = tl.program_id(0)
    num_h = tl.cdiv(H, BLOCK_H)
    pid_k = pid // num_h
    pid_h = pid % num_h

    offs_k = pid_k * BLOCK_K + tl.arange(0, BLOCK_K)
    offs_h = pid_h * BLOCK_H + tl.arange(0, BLOCK_H)
    offs_c = 4 * pid_h * BLOCK_H + tl.arange(0, 4 * BLOCK_H)
    m = (offs_h < H)[:, None] & (offs_k < K)[None, :]

    src = w_ptr + offs_h[:, None] * K + offs_k[None, :]

    vi = tl.trans((tl.load(src, mask=m, other=0).to(tl.float32) - zp) * scale)
    vf = tl.trans((tl.load(src + H * K, mask=m, other=0).to(tl.float32) - zp) * scale)
    vg = tl.trans(
        (tl.load(src + 2 * H * K, mask=m, other=0).to(tl.float32) - zp) * scale
    )
    vo = tl.trans(
        (tl.load(src + 3 * H * K, mask=m, other=0).to(tl.float32) - zp) * scale
    )

    # Interleave the four gates into one (BLOCK_K, 4*BLOCK_H) tile and store it
    # contiguously. The previous form issued four stores strided by the gate
    # index, touching only 1/4 of every cache line (measured ~109 GB/s).
    # join(join(i,g), join(f,o)) flattens as (h, x, y) -> i,f,g,o = 4h + gate.
    tile = tl.join(tl.join(vi, vg), tl.join(vf, vo))
    tile = tl.reshape(tile, (BLOCK_K, 4 * BLOCK_H))
    tl.store(
        out_ptr + offs_k[:, None] * (4 * H) + offs_c[None, :],
        tile.to(out_ptr.dtype.element_ty),
        mask=(offs_k < K)[:, None] & (offs_c < 4 * H)[None, :],
    )


@triton.jit
def _input_gemm_kernel(
    x_ptr,
    wt_ptr,
    gx_ptr,
    M,
    KIN,
    H,
    X_RS,
    GX_RS,
    X_SCALE,
    X_ZP,
    IS_INT8: tl.constexpr,
    BLOCK_M: tl.constexpr,
    BLOCK_H: tl.constexpr,
    BLOCK_K: tl.constexpr,
):
    """gx[m, 4h+gate] = sum_k x[m,k] * W_ih^T[k, 4h+gate] for m in [0, M).

    A quantized activation stream is dequantised in-register, which removes the
    standalone input-dequantisation launch and its fp32 round trip.  The value
    is identical: (v - zp) * scale is formed in fp32 and then rounded to the
    activation dtype, exactly as the separate kernel did.
    """
    pid = tl.program_id(0)
    num_h = tl.cdiv(H, BLOCK_H)
    pid_m = pid // num_h
    pid_h = pid % num_h

    offs_m = pid_m * BLOCK_M + tl.arange(0, BLOCK_M)
    m_m = offs_m < M
    offs_c = 4 * pid_h * BLOCK_H + tl.arange(0, 4 * BLOCK_H)
    m_c = offs_c < 4 * H

    acc = tl.zeros((BLOCK_M, 4 * BLOCK_H), dtype=tl.float32)
    DT = wt_ptr.dtype.element_ty

    for k0 in range(0, tl.cdiv(KIN, BLOCK_K)):
        offs_k = k0 * BLOCK_K + tl.arange(0, BLOCK_K)
        xm = m_m[:, None] & (offs_k < KIN)[None, :]
        xv = tl.load(
            x_ptr + offs_m[:, None] * X_RS + offs_k[None, :],
            mask=xm,
            other=0,
        )
        if IS_INT8:
            x = (xv.to(tl.float32) - X_ZP) * X_SCALE
        else:
            x = xv
        x = x.to(DT)
        w = tl.load(
            wt_ptr + offs_k[:, None] * (4 * H) + offs_c[None, :],
            mask=(offs_k < KIN)[:, None] & m_c[None, :],
            other=0.0,
        )
        acc += tl.dot(x, w, input_precision="ieee")

    tl.store(
        gx_ptr + offs_m[:, None] * GX_RS + offs_c[None, :],
        acc,
        mask=m_m[:, None] & m_c[None, :],
    )


@triton.jit
def _lstm_step_kernel(
    gx_ptr,
    h_ptr,
    c_ptr,
    wt_ptr,
    bih_ptr,
    bhh_ptr,
    hout_ptr,
    cout_ptr,
    out_ptr,
    N,
    KOUT,
    H,
    GX_RS,
    OUT_RS,
    HAS_BIAS: tl.constexpr,
    BLOCK_N: tl.constexpr,
    BLOCK_H: tl.constexpr,
    BLOCK_K: tl.constexpr,
):
    pid = tl.program_id(0)
    num_h = tl.cdiv(H, BLOCK_H)
    pid_n = pid // num_h
    pid_h = pid % num_h

    offs_n = pid_n * BLOCK_N + tl.arange(0, BLOCK_N)
    m_n = offs_n < N
    offs_h = pid_h * BLOCK_H + tl.arange(0, BLOCK_H)
    m_h = offs_h < H
    offs_c = 4 * pid_h * BLOCK_H + tl.arange(0, 4 * BLOCK_H)
    m_c = offs_c < 4 * H

    # precomputed x_t @ W_ih^T for this timestep, gate-interleaved columns
    acc = tl.load(
        gx_ptr + offs_n[:, None] * GX_RS + offs_c[None, :],
        mask=m_n[:, None] & m_c[None, :],
        other=0.0,
    )

    DT = wt_ptr.dtype.element_ty

    # h_{t-1} @ W_hh^T  (reduce over hidden_size), one dot per K block
    for k0 in range(0, tl.cdiv(KOUT, BLOCK_K)):
        offs_k = k0 * BLOCK_K + tl.arange(0, BLOCK_K)
        h = tl.load(
            h_ptr + offs_n[:, None] * KOUT + offs_k[None, :],
            mask=m_n[:, None] & (offs_k < KOUT)[None, :],
            other=0.0,
        ).to(DT)
        w = tl.load(
            wt_ptr + offs_k[:, None] * (4 * H) + offs_c[None, :],
            mask=(offs_k < KOUT)[:, None] & m_c[None, :],
            other=0.0,
        )
        acc += tl.dot(h, w, input_precision="ieee")

    # interleaved columns hold [h, gate] pairs: split off gate bit 0, then bit 1
    g4 = tl.reshape(acc, (BLOCK_N, BLOCK_H, 2, 2))
    even, odd = tl.split(g4)
    acc_i, acc_g = tl.split(even)
    acc_f, acc_o = tl.split(odd)

    if HAS_BIAS:
        bh = tl.load(bih_ptr + offs_h, mask=m_h, other=0.0).to(tl.float32)
        acc_i += bh[None, :]
        bh = tl.load(bih_ptr + H + offs_h, mask=m_h, other=0.0)
        acc_f += bh[None, :]
        bh = tl.load(bih_ptr + 2 * H + offs_h, mask=m_h, other=0.0)
        acc_g += bh[None, :]
        bh = tl.load(bih_ptr + 3 * H + offs_h, mask=m_h, other=0.0)
        acc_o += bh[None, :]

        bh = tl.load(bhh_ptr + offs_h, mask=m_h, other=0.0)
        acc_i += bh[None, :]
        bh = tl.load(bhh_ptr + H + offs_h, mask=m_h, other=0.0)
        acc_f += bh[None, :]
        bh = tl.load(bhh_ptr + 2 * H + offs_h, mask=m_h, other=0.0)
        acc_g += bh[None, :]
        bh = tl.load(bhh_ptr + 3 * H + offs_h, mask=m_h, other=0.0)
        acc_o += bh[None, :]

    gate_i = tl.sigmoid(acc_i)
    gate_f = tl.sigmoid(acc_f)
    gate_g = 2.0 * tl.sigmoid(2.0 * acc_g) - 1.0
    gate_o = tl.sigmoid(acc_o)

    st = m_n[:, None] & m_h[None, :]
    # h0/c0 slices may be fed straight in, so accept any fp16/bf16/fp32 source.
    c_prev = tl.load(
        c_ptr + offs_n[:, None] * H + offs_h[None, :], mask=st, other=0.0
    ).to(tl.float32)

    cy = gate_f * c_prev + gate_i * gate_g
    hy = gate_o * (2.0 * tl.sigmoid(2.0 * cy) - 1.0)

    hoff = offs_n[:, None] * H + offs_h[None, :]
    tl.store(cout_ptr + hoff, cy, mask=st)
    tl.store(hout_ptr + hoff, hy, mask=st)
    tl.store(
        out_ptr + offs_n[:, None] * OUT_RS + offs_h[None, :],
        hy.to(out_ptr.dtype.element_ty),
        mask=st,
    )


@triton.jit
def _dropout_kernel(x_ptr, seed, p, n_elements, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    m = offs < n_elements
    x = tl.load(x_ptr + offs, mask=m, other=0.0)
    r = tl.rand(seed, offs)
    keep = r >= p
    x = tl.where(keep, x / (1.0 - p), 0.0)
    tl.store(x_ptr + offs, x, mask=m)


def _unpack_param(param):
    """(w_ih, w_hh, b_ih, b_hh) from one layer/direction parameter entry."""
    if hasattr(param, "param"):
        param = param.param
    if isinstance(param, torch.ScriptObject):
        state = param.__getstate__()[0]
        packed = state[4]
        w_ih, b_ih = packed[0].unpack()
        w_hh, b_hh = packed[1].unpack()
        if b_ih is None and len(state[1]) > 0:
            b_ih = state[1][0]
        if b_hh is None and len(state[1]) > 1:
            b_hh = state[1][1]
        return w_ih, w_hh, b_ih, b_hh
    return (
        param[0],
        param[1],
        param[2] if len(param) > 2 else None,
        param[3] if len(param) > 3 else None,
    )


_PIN_KEEPALIVE = []


def _to_device(src, device):
    """Move a host tensor to the device through a pinned staging buffer.

    Profiling shows 84-93% of the measured latency is outside every kernel and
    scales at ~3.9 ms/MiB with the int8 weight payload, so the payload is staged
    through page-locked memory and copied asynchronously on the current stream.
    The staging buffer is held until the copy has certainly completed.  Nothing
    is cached across calls: every buffer is rewritten from the current argument
    before it is used.
    """
    if src.device == device:
        return src
    if src.device.type == "cpu" and device.type != "cpu":
        try:
            pin = torch.empty(src.shape, dtype=src.dtype, pin_memory=True)
            pin.copy_(src)
        except Exception:
            return src.to(device)
        dst = pin.to(device, non_blocking=True)
        _PIN_KEEPALIVE.append(pin)
        if len(_PIN_KEEPALIVE) > 64:
            del _PIN_KEEPALIVE[:32]
        return dst
    return src.to(device)


def _int8_payload(w):
    """Zero-copy int8/uint8 view of a per-tensor quantized tensor's payload.

    For per-tensor affine quantization the tensor's storage *is* the integer
    payload in the tensor's own shape and strides, so a view avoids the
    payload-sized host copy int_repr() performs.  Profiling put ~30% of the
    large-shape latency outside every kernel, scaling with the int8 weight
    payload - i.e. with those host copies - so removing one of the two copies
    per matrix is the remaining host-side lever.  Falls back to int_repr() for
    any layout or dtype where the identity does not hold, so the bytes handed to
    the dequantisation kernel are unchanged either way.
    """
    if w.dtype == torch.qint8:
        dt = torch.int8
    elif w.dtype == torch.quint8:
        dt = torch.uint8
    else:
        return w.int_repr()
    try:
        return torch.empty(0, dtype=dt).set_(
            w.untyped_storage(), w.storage_offset(), tuple(w.shape), tuple(w.stride())
        )
    except Exception:
        return w.int_repr()


def _dequant_weight(w, device, odtype):
    """(K, 4H) odtype tensor, column h*4 + gate, holding (w_int - zp) * scale."""
    if w.is_quantized:
        if w.qscheme() != torch.per_tensor_affine:
            raise NotImplementedError("only per-tensor quantized weights supported")
        src = _int8_payload(w)
        scale = float(w.q_scale())
        zp = float(w.q_zero_point())
    else:
        src = w
        scale = 1.0
        zp = 0.0
    src = _to_device(src.contiguous(), device)
    rows, k = src.shape
    h = rows // 4
    out = torch.empty((k, rows), device=device, dtype=odtype)
    if src.numel():
        bk, bhh = 64, 32
        grid = (triton.cdiv(k, bk) * triton.cdiv(h, bhh),)
        _dequant_t_kernel[grid](
            src, out, k, h, scale, zp, BLOCK_K=bk, BLOCK_H=bhh, num_warps=8
        )
    return out


def _prep_bias(b, device):
    if b is None:
        return torch.zeros(1, device=device, dtype=torch.float32)
    return _to_device(b.to(dtype=torch.float32).contiguous(), device)


def quantized_lstm(
    input,
    hx,
    params,
    has_biases,
    num_layers,
    dropout,
    train,
    bidirectional,
    batch_first,
    dtype=None,
    use_dynamic=False,
):
    if batch_first:
        input = input.transpose(0, 1)

    if input.is_quantized:
        x_scale = float(input.q_scale())
        x_zp = float(input.q_zero_point())
        xi = input.int_repr()
        if xi.device != hx[0].device:
            xi = xi.to(hx[0].device)
        xi = xi.contiguous()
        x_is_int8 = True
        odtype = hx[0].dtype
    else:
        xi = input.contiguous()
        x_scale = 0.0
        x_zp = 0.0
        x_is_int8 = False
        odtype = xi.dtype

    device = hx[0].device
    T, N, KIN = xi.shape
    h0, c0 = hx[0], hx[1]
    H = h0.shape[-1]
    num_directions = 2 if bidirectional else 1
    DH = num_directions * H
    params_per_layer = max(1, len(params) // num_layers)

    # Returned tensors are produced in the activation dtype directly, so no
    # final cast kernel is needed: the step kernel's stores convert on the way
    # out, which is exactly the fp32-value-then-cast the reference performs.
    out = torch.empty((T, N, DH), device=device, dtype=odtype)
    hy = torch.empty((num_layers * num_directions, N, H), device=device, dtype=odtype)
    cy = torch.empty_like(hy)
    # Only a multi-layer fp32 run needs a separate in-place fp32 activation
    # stream besides `out`; every other case writes the stream straight into
    # `out` (fp32 dtype, or the final layer whose output is only returned).
    fp32_out = odtype == torch.float32
    y32 = None
    if not fp32_out and num_layers > 1:
        y32 = torch.empty((T, N, DH), device=device, dtype=torch.float32)

    layer_input = xi
    in_is_int8 = x_is_int8
    layer_kin = KIN
    n_elem = T * N * DH

    for layer in range(num_layers):
        kin = layer_kin
        last_layer = layer == num_layers - 1
        stream = out if (last_layer or fp32_out) else y32
        for d in range(num_directions):
            w_ih, w_hh, b_ih, b_hh = _unpack_param(params[layer * params_per_layer + d])
            wi = _dequant_weight(w_ih, device, odtype)
            wh = _dequant_weight(w_hh, device, odtype)
            has_b = bool(has_biases) and b_ih is not None and b_hh is not None
            bi = _prep_bias(b_ih, device)
            bh_b = _prep_bias(b_hh, device)

            kout = wh.shape[0]
            # The first step reads h0/c0 directly (the kernel already rounds the
            # loaded state to the activation dtype, exactly as the reference
            # does) and the last step writes hy/cy directly, so no state
            # copy_ launches are needed at either end.  Two alternating scratch
            # buffers cover the intermediate steps.
            h_prev = h0[layer * num_directions + d]
            c_prev = c0[layer * num_directions + d]
            h_a = torch.empty((N, H), device=device, dtype=torch.float32)
            h_b = torch.empty_like(h_a)
            c_a = torch.empty_like(h_a)
            c_b = torch.empty_like(h_a)
            h_final = hy[layer * num_directions + d]
            c_final = cy[layer * num_directions + d]

            if layer == 0:
                xacts, x_rs = layer_input, kin
            else:
                xacts = layer_input[:, :, d * H : (d + 1) * H]
                x_rs = DH

            # Precompute the recurrence-free gate term for every timestep at once.
            tn = T * N
            gx = torch.empty((tn, 4 * H), device=device, dtype=torch.float32)
            g_bm, g_bh = 64, 32
            g_grid = (triton.cdiv(tn, g_bm) * triton.cdiv(H, g_bh),)
            x_int8 = layer == 0 and in_is_int8
            _input_gemm_kernel[g_grid](
                xacts,
                wi,
                gx,
                tn,
                kin,
                H,
                x_rs,
                4 * H,
                x_scale,
                x_zp,
                IS_INT8=x_int8,
                BLOCK_M=g_bm,
                BLOCK_H=g_bh,
                BLOCK_K=64,
                num_warps=8,
                num_stages=3,
            )

            reverse = d == 1
            bn, bh, bk, warps = _pick_config(N, H)
            # Round-5 profiling: a step launch costs ~5 us plus ~7-10 us per
            # K-block dot invocation, flat in tile width, operand bytes, warp
            # count and epilogue size (the dot work itself is ~0.14 us per
            # iteration), and a second stage buffer measurably hurt (13-22%
            # slower per iteration).  The lever is the *number* of K-block
            # iterations, so take the largest BLOCK_K whose staged tiles fit the
            # ~96 KiB footprint the fp32 path already uses, with one buffer.
            if odtype != torch.float32:
                bk = 256 if kout >= 256 else (128 if kout >= 128 else 64)
            else:
                bk = 128 if kout >= 128 else 64
            stages = 1
            grid = (triton.cdiv(N, bn) * triton.cdiv(H, bh),)
            for step in range(T):
                t = T - 1 - step if reverse else step
                if step == T - 1:
                    h_out, c_out = h_final, c_final
                elif step % 2 == 0:
                    h_out, c_out = h_a, c_a
                else:
                    h_out, c_out = h_b, c_b
                _lstm_step_kernel[grid](
                    gx[t * N : (t + 1) * N],
                    h_prev,
                    c_prev,
                    wh,
                    bi,
                    bh_b,
                    h_out,
                    c_out,
                    stream[t, :, d * H : (d + 1) * H],
                    N,
                    kout,
                    H,
                    4 * H,
                    DH,
                    HAS_BIAS=has_b,
                    BLOCK_N=bn,
                    BLOCK_H=bh,
                    BLOCK_K=bk,
                    num_warps=warps,
                    num_stages=stages,
                )
                h_prev, c_prev = h_out, c_out

        # the next layer reads the fp32 activation stream in place
        layer_input = stream
        layer_kin = DH
        in_is_int8 = False
        if train and dropout > 0.0 and layer < num_layers - 1:
            _dropout_kernel[(triton.cdiv(n_elem, 1024),)](
                stream, 1337, float(dropout), n_elem, BLOCK=1024, num_warps=4
            )

    if batch_first:
        out = out.transpose(0, 1)
    return out, hy, cy
